def editorial(hotel, lang):
    copy = TEXT[lang]
    name = hotel['display_name']
    if lang == 'en' and hotel.get('blog_content_en'):
        parts = hotel['blog_content_en'].split('\n\n')
        if len(parts) != 4:
            raise ValueError(f'Unexpected English paragraph structure: {name}')
        intro = parts[0]
        comparison = parts[1].partition('? ')[2] or parts[1]
        inspiration = parts[2].removeprefix('Travel inspiration: ')
        return hotel['seo_title_en'], intro, [(copy[2].format(name=name),comparison),(copy[4],inspiration)]
    return name+' | '+copy[0], copy[1].format(name=name), [(copy[2].format(name=name),copy[3]),(copy[4],copy[5])]
